def grep(item, path, debug, **kwargs):
    ignore_case = kwargs.get('ignore_case', False)
    exact_match = kwargs.get('exact_match', False)
    exclude_paths = kwargs.get('exclude_paths', [])
    exclude_regex_paths = kwargs.get('exclude_regex_paths', [])
    verbose_level = kwargs.get('verbose_level', 1)

    try:
        content = load_path_content(path)
    except Exception as e:
        if debug:
            raise
        else:
            sys.exit(str(f"Error when loading {path}: {e}"))

    try:
        search = DeepSearch(
            content,
            item,
            ignore_case=ignore_case,
            exact_match=exact_match,
            exclude_paths=exclude_paths,
            exclude_regex_paths=exclude_regex_paths,
            verbose_level=verbose_level
        )
        result = search.to_dict()
        pprint(result, indent=2)
    except Exception as e:
        if debug:
            raise
        else:
            sys.exit(str(e))
